import{c as t,Q as a,j as r,m as s}from"./chunks/framework.W-g_WCNV.js";const m=JSON.parse('{"title":"Password policy","description":"How passwords are hashed, minimum length, and forced reset on first login.","frontmatter":{"title":"Password policy","description":"How passwords are hashed, minimum length, and forced reset on first login."},"headers":[],"relativePath":"security/password-policy.md","filePath":"security/password-policy.md"}'),o={name:"security/password-policy.md"};function i(n,e,d,h,l,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h2 id="hashing-algorithm" tabindex="-1">Hashing algorithm <a class="header-anchor" href="#hashing-algorithm" aria-label="Permalink to &quot;Hashing algorithm&quot;">​</a></h2><p>GateKeeper uses <strong>argon2id</strong> for all password hashing. Argon2id is the winner of the Password Hashing Competition and is recommended by OWASP for new applications.</p><p>The specific parameters used:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Value</th></tr></thead><tbody><tr><td>Memory</td><td>64 MB</td></tr><tr><td>Iterations</td><td>3</td></tr><tr><td>Parallelism</td><td>4</td></tr><tr><td>Output length</td><td>32 bytes</td></tr><tr><td>Salt length</td><td>16 bytes (random per hash)</td></tr></tbody></table><p>These match the OWASP recommended minimum for argon2id. They mean each password verification takes roughly 100-200ms on typical hardware, which is slow enough to make brute-force attacks impractical.</p><p>A new random salt is generated for every hash, so two users with the same password have different hashes in the database.</p><h2 id="policy-settings" tabindex="-1">Policy settings <a class="header-anchor" href="#policy-settings" aria-label="Permalink to &quot;Policy settings&quot;">​</a></h2><p>The policy is configured under <strong>Settings - Password policy</strong> and applies immediately, with no restart.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Range</th></tr></thead><tbody><tr><td>Minimum length</td><td>12</td><td>8 to 128</td></tr><tr><td>Require at least one uppercase letter</td><td>Off</td><td>On or off</td></tr><tr><td>Require at least one number</td><td>Off</td><td>On or off</td></tr><tr><td>Require at least one symbol</td><td>Off</td><td>On or off</td></tr></tbody></table><p>There is no maximum length.</p><h3 id="where-it-applies" tabindex="-1">Where it applies <a class="header-anchor" href="#where-it-applies" aria-label="Permalink to &quot;Where it applies&quot;">​</a></h3><p>The policy is enforced server-side on every path that sets a password:</p><ul><li>Self-registration</li><li>Password reset through the forgot-password email</li><li>A user changing their own password</li><li>An admin creating a user with a temporary password</li><li>An admin setting or resetting a user&#39;s password</li><li>Creating an admin account, promoting a user to admin, and the first-run setup page</li><li>An admin changing their own password</li></ul><p>The form fields also carry the configured minimum, so the browser shows the same requirement the server enforces.</p><h3 id="choosing-a-policy" tabindex="-1">Choosing a policy <a class="header-anchor" href="#choosing-a-policy" aria-label="Permalink to &quot;Choosing a policy&quot;">​</a></h3><p>Length does more for password strength than character rules, so raising the minimum is usually a better move than switching the character requirements on. Requirements like &quot;must contain a symbol&quot; tend to push people toward predictable shapes such as <code>Password1!</code>.</p><p>The character requirements exist because many organisations have to meet a written standard that names them. If that applies to you, turn on what you need. If it does not, a longer minimum with the requirements left off is the stronger setting.</p><h2 id="forced-password-change" tabindex="-1">Forced password change <a class="header-anchor" href="#forced-password-change" aria-label="Permalink to &quot;Forced password change&quot;">​</a></h2><p>When an admin creates a user or directly sets a password, the <code>force_password_change</code> flag is set. The user is redirected to <code>/profile/password</code> before they can access anything else, and they cannot skip this step.</p><p>After the user sets their own password, the flag is cleared.</p><h2 id="reset-token-security" tabindex="-1">Reset token security <a class="header-anchor" href="#reset-token-security" aria-label="Permalink to &quot;Reset token security&quot;">​</a></h2><p>Password reset tokens are 32 bytes of cryptographically random data. GateKeeper stores the argon2id hash of the token, not the token itself. The hash uses a fixed salt (<code>gatekeeper-reset-token-salt-v1xx</code>) applied to the raw random bytes. Tokens expire in 30 minutes and are single-use.</p>',22)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
